insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_alg1_v1'
from (values
('111.39.c.2.A',3,'A taxi charges $3 plus $2 per mile. For trips of at most 10 miles, which is a reasonable domain for the cost function?','["0 ≤ x ≤ 10", "3 ≤ x ≤ 23", "x ≥ 3", "all negative numbers"]'::jsonb,0,'Miles driven range from 0 to 10.','original'),
('111.39.c.2.A',2,'What are the domain and range of f(x) = 2x + 1 when x can be any real number?','["domain all reals, range y = 1", "both all real numbers", "domain x ≥ 1, range all reals", "domain x ≥ 0, range y ≥ 1"]'::jsonb,1,'A non-constant line takes every real input and output.','original'),
('111.39.c.2.A',3,'A tank is filled at 5 gallons per minute for 20 minutes. If g(t) = 5t, what is a reasonable range?','["g ≥ 100", "0 ≤ g ≤ 20", "0 ≤ g ≤ 100", "all real numbers"]'::jsonb,2,'At t = 20, g = 100 gallons.','original'),
('111.39.c.2.B',2,'Which equation has slope 3 and y-intercept -2?','["y = −2x + 3", "y = 3x + 2", "y = x − 6", "y = 3x − 2"]'::jsonb,3,'Slope-intercept form is y = mx + b.','original'),
('111.39.c.2.B',3,'Which is the point-slope form of the line with slope 4 through (2, 5)?','["y − 5 = 4(x − 2)", "y + 5 = 4(x + 2)", "y = 4x + 5", "y − 2 = 4(x − 5)"]'::jsonb,0,'Point-slope form is y − y₁ = m(x − x₁).','original'),
('111.39.c.2.B',3,'Write y = 2x + 3 in standard form Ax + By = C.','["−2x − y = 3", "2x − y = −3", "2x + y = 3", "x − 2y = 3"]'::jsonb,1,'Subtract y from both sides: 2x − y = −3.','original'),
('111.39.c.2.C',3,'A table shows (0, 4), (1, 7), (2, 10). Which equation fits these points?','["y = 3x + 7", "y = 4x + 3", "y = 3x + 4", "y = 7x + 4"]'::jsonb,2,'Constant change of 3 and y-intercept 4.','original'),
('111.39.c.2.C',3,'A line on a graph passes through (0, −1) and (2, 3). Which equation describes it?','["y = 2x + 1", "y = 3x − 1", "y = −x + 2", "y = 2x − 1"]'::jsonb,3,'Slope (3 − (−1))/2 = 2; y-intercept −1.','original'),
('111.39.c.2.C',3,'A savings account starts with $50 and adds $10 each week. Which equation gives the balance y after x weeks?','["y = 10x + 50", "y = 10x − 50", "y = 60x", "y = 50x + 10"]'::jsonb,0,'Rate is 10 per week; start is 50.','original'),
('111.39.c.2.D',3,'If y varies directly with x and y = 3 when x = 2, what is the constant of variation k?','["5", "1.5", "6", "0.67"]'::jsonb,1,'k = y/x = 3/2 = 1.5.','original'),
('111.39.c.2.D',3,'y varies directly with x. If y = 20 when x = 4, what is y when x = 7?','["45", "28", "35", "27"]'::jsonb,2,'k = 5, so y = 5(7) = 35.','original'),
('111.39.c.2.D',2,'Which equation represents a direct variation?','["y = x + 5", "y = 5x + 1", "y = 5 − x", "y = 5x"]'::jsonb,3,'Direct variation has the form y = kx.','original'),
('111.39.c.2.E',3,'Which line passes through (1, 5) and is parallel to y = 2x + 1?','["y = 2x + 3", "y = x + 4", "y = −½x + 5.5", "y = 2x + 5"]'::jsonb,0,'Same slope 2; 5 = 2(1) + b gives b = 3.','original'),
('111.39.c.2.E',3,'A line parallel to y = −3x + 4 passes through the origin. Its equation is...','["y = ⅓x", "y = −3x", "y = −3x + 4", "y = 3x"]'::jsonb,1,'Same slope, b = 0.','original'),
('111.39.c.2.E',4,'Which line is parallel to y = ½x − 2 and contains (4, 1)?','["y = ½x + 1", "y = −2x + 9", "y = ½x − 1", "y = 2x − 7"]'::jsonb,2,'1 = ½(4) + b gives b = −1.','original'),
('111.39.c.2.F',3,'What is the slope of a line perpendicular to y = 2x + 1?','["½", "−2", "2", "−½"]'::jsonb,3,'Perpendicular slopes are negative reciprocals.','original'),
('111.39.c.2.F',4,'Which line contains (4, 3) and is perpendicular to y = 2x + 1?','["y = −½x + 5", "y = 2x − 5", "y = −½x + 3", "y = ½x + 1"]'::jsonb,0,'Slope −½; 3 = −2 + b gives b = 5.','original'),
('111.39.c.2.F',3,'A line perpendicular to y = −3x passes through the origin. Its equation is...','["y = −⅓x", "y = ⅓x", "y = 3x", "y = −3x + 1"]'::jsonb,1,'Negative reciprocal of −3 is ⅓.','original'),
('111.39.c.2.G',2,'Which equation describes the line through (3, 5) and (3, −2)?','["y = 5", "y = 3", "x = 3", "x = −2"]'::jsonb,2,'Both points have x = 3, so the line is vertical.','original'),
('111.39.c.2.G',2,'The line through (−1, 4) that is parallel to the x-axis has the equation...','["x = −1", "x = 4", "y = x + 5", "y = 4"]'::jsonb,3,'A horizontal line has constant y.','original'),
('111.39.c.2.G',3,'What is the slope of the line x = 7?','["undefined", "7", "0", "1"]'::jsonb,0,'A vertical line has undefined slope.','original'),
('111.39.c.2.H',3,'A graph shows a dashed boundary line with slope 2 and y-intercept 1, and the region below the line is shaded. Which inequality is shown?','["y > 2x + 1", "y < 2x + 1", "y ≤ 2x + 1", "y ≥ 2x + 1"]'::jsonb,1,'Dashed means strict; below means less than.','original'),
('111.39.c.2.H',3,'Sam spends no more than $20 on x pencils at $2 each and y notebooks at $4 each. Which inequality models this?','["4x + 2y ≤ 20", "2x + 4y ≥ 20", "2x + 4y ≤ 20", "2x + 4y = 20"]'::jsonb,2,'Total cost cannot exceed 20.','original'),
('111.39.c.2.H',3,'You need at least $12 from x small bags selling at $3 and y large bags at $2. Which inequality works?','["3x + 2y ≤ 12", "3x + 2y > 12 only", "2x + 3y ≥ 12", "3x + 2y ≥ 12"]'::jsonb,3,'At least means ≥.','original'),
('111.39.c.2.I',3,'Plan A costs $20 plus $5 per month; Plan B costs $5 plus $10 per month. Which system models the costs y after x months?','["y = 5x + 20 and y = 10x + 5", "y = 25x and y = 15x", "y = 20x + 5 and y = 5x + 10", "y = 5x + 5 and y = 10x + 20"]'::jsonb,0,'Each plan is start fee plus rate times months.','original'),
('111.39.c.2.I',4,'A theater sells 100 tickets: adults at $8, children at $5, for $620 total. Which system models x adults and y children?','["x + y = 100 and 5x + 8y = 620", "x + y = 100 and 8x + 5y = 620", "8x + 5y = 100 and x = y", "x + y = 620 and 8x + 5y = 100"]'::jsonb,1,'One equation counts tickets, one totals money.','original'),
('111.39.c.2.I',3,'A graph shows two lines crossing at (2, 4). Line 1 has slope 1 and Line 2 has slope −1. Which system fits?','["y = 2x and y = −2x + 8", "y = x + 2 and y = x + 6", "y = x + 2 and y = −x + 6", "y = x + 4 and y = −x + 2"]'::jsonb,2,'Each line passes through (2, 4).','original'),
('111.39.c.3.A',2,'What is the slope of the line through (1, 2) and (3, 8)?','["2", "6", "1/3", "3"]'::jsonb,3,'(8 − 2)/(3 − 1) = 3.','original'),
('111.39.c.3.A',3,'A table shows x: 0, 2, 4 and y: 1, 5, 9. What is the slope?','["2", "1", "4", "½"]'::jsonb,0,'y increases 4 when x increases 2.','original'),
('111.39.c.3.A',3,'What is the slope of the line 4x + 2y = 8?','["−4", "−2", "4", "2"]'::jsonb,1,'y = −2x + 4.','original'),
('111.39.c.3.B',2,'A car travels 150 miles in 3 hours. What is the rate of change of distance with respect to time?','["450 miles per hour", "150 miles per hour", "50 miles per hour", "3 miles per hour"]'::jsonb,2,'150 ÷ 3 = 50.','original'),
('111.39.c.3.B',3,'For f(x) = −4x + 30 modeling water left in a tank (gallons) after x minutes, the rate of change is...','["30 gallons per minute", "26 gallons per minute", "4 gallons per minute", "−4 gallons per minute"]'::jsonb,3,'Slope is −4: it drains 4 gallons each minute.','original'),
('111.39.c.3.B',3,'A graph passes through (2, 10) and (6, 22). What is its rate of change?','["3", "4", "12", "5.5"]'::jsonb,0,'(22 − 10)/(6 − 2) = 3.','original'),
('111.39.c.3.C',2,'What is the y-intercept of y = 2x − 6?','["2", "−6", "3", "6"]'::jsonb,1,'Set x = 0.','original'),
('111.39.c.3.C',3,'What are the intercepts of 3x + 4y = 12?','["x-intercept 12, y-intercept 12", "x-intercept 3, y-intercept 4", "x-intercept 4, y-intercept 3", "x-intercept −4, y-intercept −3"]'::jsonb,2,'Set y = 0, then x = 0.','original'),
('111.39.c.3.C',3,'What is the zero of f(x) = x + 5?','["5", "0", "1", "−5"]'::jsonb,3,'Solve x + 5 = 0.','original'),
('111.39.c.3.D',3,'Which point is a solution of y > 3x − 2?','["(1, 2)", "(1, 1)", "(0, −3)", "(2, 4)"]'::jsonb,0,'2 > 3(1) − 2 = 1 is true.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Mathematics' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_alg1_v1'
from (values
('111.39.c.3.D',3,'The graph of y ≥ 2x − 1 has what kind of boundary line and shading?','["dashed line, shaded below", "solid line, shaded above", "solid line, shaded below", "dashed line, shaded above"]'::jsonb,1,'≥ is solid; greater means above.','original'),
('111.39.c.3.D',3,'Testing (0, 0) in y < x + 2 gives a true statement. Which region is shaded?','["only the line", "the side not containing the origin", "the side containing the origin", "no region"]'::jsonb,2,'Shade the side where the test point is a solution.','original'),
('111.39.c.3.E',2,'How does the graph of g(x) = x + 3 compare to f(x) = x?','["steeper", "shifted right 3 units", "reflected across the x-axis", "shifted up 3 units"]'::jsonb,3,'Adding d shifts vertically.','original'),
('111.39.c.3.E',3,'How does g(x) = 2x compare to f(x) = x?','["steeper (vertical stretch by 2)", "shifted up 2", "shifted left 2", "flatter"]'::jsonb,0,'Multiplying by a > 1 stretches the graph.','original'),
('111.39.c.3.E',3,'How does g(x) = −x compare to f(x) = x?','["stretched by 2", "reflected across the x-axis", "shifted down 1", "reflected across the line y = x"]'::jsonb,1,'Multiplying by −1 flips vertically.','original'),
('111.39.c.3.F',3,'Lines y = x + 1 and y = −x + 3 intersect at which point?','["(0, 1)", "(3, 0)", "(1, 2)", "(2, 1)"]'::jsonb,2,'x + 1 = −x + 3 gives x = 1, y = 2.','original'),
('111.39.c.3.F',3,'Two lines with the same slope and different y-intercepts have how many solutions as a system?','["two", "infinitely many", "one", "none"]'::jsonb,3,'They are parallel and never meet.','original'),
('111.39.c.3.F',3,'The system y = 2x + 1 and 2y = 4x + 2 has how many solutions?','["infinitely many", "none", "one", "two"]'::jsonb,0,'The equations describe the same line.','original'),
('111.39.c.3.G',3,'Plan A costs 10 + 2x and Plan B costs 4x. On a graph the lines cross at x = 5. What does that mean?','["Plan B costs 10 at x = 0", "both plans cost the same at 5 uses", "the plans never match", "Plan A is free at 5"]'::jsonb,1,'The intersection is where costs are equal.','original'),
('111.39.c.3.G',3,'Graphs of two bike rentals cross near (3, 18). What does the point tell you?','["the rentals never cost the same", "one rental is free", "after about 3 hours both cost about $18", "both cost $3 after 18 hours"]'::jsonb,2,'Coordinates give the shared time and cost.','original'),
('111.39.c.3.G',4,'If two cost lines never intersect on the graph for x ≥ 0, what can you conclude?','["the graph is wrong", "the costs are equal at 0", "both options cost the same", "one option is always cheaper"]'::jsonb,3,'Parallel lines never cross.','original'),
('111.39.c.3.H',3,'For the system y > x and y < 4, which point is in the solution region?','["(1, 3)", "(1, 5)", "(3, 1)", "(5, 2)"]'::jsonb,0,'Need y > x and y < 4; (1, 3) works.','original'),
('111.39.c.3.H',3,'The solution to a system of two inequalities on a graph is...','["the area outside both regions", "the region where the shaded areas overlap", "only where the lines cross", "just one of the shaded regions"]'::jsonb,1,'Points must satisfy both inequalities.','original'),
('111.39.c.3.H',4,'Is (2, 2) a solution of the system y ≥ x and y ≤ 2x?','["no, it fails y ≥ x", "only if x is negative", "yes", "no, it fails y ≤ 2x"]'::jsonb,2,'2 ≥ 2 and 2 ≤ 4.','original'),
('111.39.c.4.A',3,'A correlation coefficient r = 0.95 means the data show...','["no relationship", "a perfect causal link", "a strong negative relationship", "a strong positive linear relationship"]'::jsonb,3,'Close to +1 means strong positive.','original'),
('111.39.c.4.A',3,'Which correlation coefficient shows the strongest linear relationship?','["−0.92", "0.40", "0.60", "−0.15"]'::jsonb,0,'The magnitude closest to 1 is strongest.','original'),
('111.39.c.4.A',3,'A correlation of r = −0.2 suggests the relationship is...','["strong and negative", "weak and negative", "perfect", "weak and positive"]'::jsonb,1,'Near 0 is weak; the sign is negative.','original'),
('111.39.c.4.B',3,'Ice cream sales and swimming accidents both rise in summer. This is evidence of...','["causation: ice cream causes accidents", "negative correlation", "association, not necessarily causation", "no relationship"]'::jsonb,2,'A hidden factor (hot weather) explains both.','original'),
('111.39.c.4.B',3,'Which statement describes causation?','["Both variables are positive", "Two variables rise at the same time", "Two variables have the same units", "Increasing one variable directly makes the other change"]'::jsonb,3,'Causation means one produces the other.','original'),
('111.39.c.4.B',3,'Students who sleep more tend to earn higher grades. What can be concluded?','["the variables are associated; more evidence is needed for causation", "sleep always causes higher grades", "grades cause sleep", "there is no relationship"]'::jsonb,0,'Association alone does not prove cause.','original'),
('111.39.c.4.C',3,'A line of best fit passes through (0, 2) and (10, 22). Which equation is it?','["y = 2x + 10", "y = 2x + 2", "y = x + 2", "y = 22x + 2"]'::jsonb,1,'Slope 20/10 = 2; intercept 2.','original'),
('111.39.c.4.C',3,'Using y = 2x + 2, predict y when x = 7.','["9", "18", "16", "14"]'::jsonb,2,'2(7) + 2 = 16.','original'),
('111.39.c.4.C',4,'A scatterplot shows a rising trend. The line of best fit is used to...','["remove outliers automatically", "change the data", "prove every point lies on the line", "estimate values and make predictions"]'::jsonb,3,'Models estimate unseen values.','original'),
('111.39.c.5.A',2,'Solve 3(x + 2) = 18.','["x = 4", "x = 8", "x = 6", "x = 5.33"]'::jsonb,0,'x + 2 = 6.','original'),
('111.39.c.5.A',3,'Solve 4(x − 1) = 2x + 6.','["x = 2.5", "x = 5", "x = 1", "x = 7"]'::jsonb,1,'4x − 4 = 2x + 6 gives 2x = 10.','original'),
('111.39.c.5.A',3,'Solve 2x − 5 = 11.','["x = 3", "x = 16", "x = 8", "x = 6"]'::jsonb,2,'2x = 16.','original'),
('111.39.c.5.B',3,'Solve 3x − 4 > 11.','["x > 15", "x < 5", "x > 7/3", "x > 5"]'::jsonb,3,'3x > 15.','original'),
('111.39.c.5.B',3,'Solve −2x ≤ 10.','["x ≥ −5", "x ≤ −5", "x ≤ 5", "x ≥ 5"]'::jsonb,0,'Dividing by a negative flips the sign.','original'),
('111.39.c.5.B',3,'Solve 2(x + 1) < 8.','["x < 4", "x < 3", "x > 3", "x < 7"]'::jsonb,1,'x + 1 < 4.','original'),
('111.39.c.5.C',3,'Solve: x + y = 10 and x − y = 2.','["(8, 2)", "(5, 5)", "(6, 4)", "(4, 6)"]'::jsonb,2,'Add the equations: 2x = 12.','original'),
('111.39.c.5.C',3,'Solve: y = 2x and x + y = 9.','["(2, 4)", "(6, 3)", "(4, 5)", "(3, 6)"]'::jsonb,3,'Substitute: 3x = 9.','original'),
('111.39.c.5.C',3,'Solve: 2x + y = 7 and x − y = 2.','["(3, 1)", "(1, 3)", "(2, 3)", "(5, −3)"]'::jsonb,0,'Add the equations: 3x = 9.','original'),
('111.39.c.6.A',3,'What is the range of y = x² + 1?','["y ≥ 0", "y ≥ 1", "y ≤ 1", "all real numbers"]'::jsonb,1,'The vertex (0, 1) is the minimum.','original'),
('111.39.c.6.A',3,'What is the range of y = −x² + 4?','["all real numbers", "y ≤ 0", "y ≤ 4", "y ≥ 4"]'::jsonb,2,'Opens down; maximum 4.','original'),
('111.39.c.6.A',2,'What is the domain of any quadratic function y = ax² + bx + c?','["x ≠ 0", "x ≥ 0", "y ≥ 0", "all real numbers"]'::jsonb,3,'Any real x can be squared.','original'),
('111.39.c.6.B',4,'A parabola has vertex (2, 3) and passes through (3, 5). Which is its vertex form?','["y = 2(x − 2)² + 3", "y = 2(x − 3)² + 2", "y = 2(x + 2)² + 3", "y = (x − 2)² + 3"]'::jsonb,0,'5 = a(1)² + 3 gives a = 2.','original'),
('111.39.c.6.B',4,'A parabola has vertex (1, −4) and passes through (0, −3). Which equation fits?','["y = (x + 1)² − 4", "y = (x − 1)² − 4", "y = 2(x − 1)² − 4", "y = −(x − 1)² − 4"]'::jsonb,1,'−3 = a + (−4) gives a = 1.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Mathematics' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_alg1_v1'
from (values
('111.39.c.6.B',4,'A parabola has vertex (−1, 2) and passes through (0, 0). Which equation fits?','["y = 2(x + 1)² + 2", "y = −2(x − 1)² + 2", "y = −2(x + 1)² + 2", "y = −(x + 1)² + 2"]'::jsonb,2,'0 = a + 2 gives a = −2.','original'),
('111.39.c.6.C',3,'A quadratic has solutions x = 2 and x = −3. Which function could it be?','["y = x² − x − 6", "y = x² + 5x + 6", "y = x² − 5x − 6", "y = x² + x − 6"]'::jsonb,3,'(x − 2)(x + 3) = x² + x − 6.','original'),
('111.39.c.6.C',3,'A graph crosses the x-axis at 1 and 5. Which equation fits?','["y = x² − 6x + 5", "y = x² − 5x + 6", "y = x² − 4x − 5", "y = x² + 6x + 5"]'::jsonb,0,'(x − 1)(x − 5) = x² − 6x + 5.','original'),
('111.39.c.6.C',3,'A parabola has zeros at 0 and 4. Which equation fits?','["y = x² + 4", "y = x² − 4x", "y = x² − 4", "y = x² + 4x"]'::jsonb,1,'x(x − 4).','original'),
('111.39.c.7.A',3,'What is the vertex of y = x² − 4x + 3?','["(2, 1)", "(4, 3)", "(2, −1)", "(−2, −1)"]'::jsonb,2,'x = 4/2 = 2; y = 4 − 8 + 3 = −1.','original'),
('111.39.c.7.A',3,'What is the y-intercept of y = x² + 2x − 8?','["8", "−4", "2", "−8"]'::jsonb,3,'Set x = 0.','original'),
('111.39.c.7.A',3,'What is the axis of symmetry of y = x² − 6x + 5?','["x = 3", "x = −3", "x = 5", "x = 6"]'::jsonb,0,'x = −b/2a = 6/2.','original'),
('111.39.c.7.B',3,'What are the zeros of y = (x − 3)(x + 2)?','["−3 and −2", "3 and −2", "3 and 2", "−3 and 2"]'::jsonb,1,'Set each factor to 0.','original'),
('111.39.c.7.B',3,'A quadratic has zeros 4 and −1. Which linear factors does it have?','["(x − 4) and (x − 1)", "(x + 4) and (x − 1)", "(x − 4) and (x + 1)", "(x + 4) and (x + 1)"]'::jsonb,2,'Zero r gives factor (x − r).','original'),
('111.39.c.7.B',3,'The graph of y = x² − 9 crosses the x-axis at...','["x = 0", "x = 3 only", "x = 9 only", "x = −3 and x = 3"]'::jsonb,3,'(x − 3)(x + 3) = 0.','original'),
('111.39.c.7.C',2,'How does y = x² + 3 differ from y = x²?','["shifted up 3 units", "reflected across the x-axis", "narrower", "shifted left 3 units"]'::jsonb,0,'Adding d moves it vertically.','original'),
('111.39.c.7.C',3,'How does y = (x − 2)² differ from y = x²?','["wider", "shifted right 2 units", "shifted up 2 units", "shifted left 2 units"]'::jsonb,1,'Replacing x with x − h shifts right by h.','original'),
('111.39.c.7.C',3,'How does y = 3x² differ from y = x²?','["opens downward", "wider", "narrower, vertical stretch by 3", "shifted up 3"]'::jsonb,2,'A larger |a| narrows the parabola.','original'),
('111.39.c.8.A',3,'Solve x² − 5x + 6 = 0.','["x = 1 or x = 6", "x = −2 or x = −3", "x = 5 or x = 1", "x = 2 or x = 3"]'::jsonb,3,'(x − 2)(x − 3).','original'),
('111.39.c.8.A',2,'Solve x² = 49.','["x = 7 or x = −7", "x = 24.5", "x = 7 only", "x = −7 only"]'::jsonb,0,'Take both square roots.','original'),
('111.39.c.8.A',4,'Use the quadratic formula to solve x² + 4x + 1 = 0.','["x = 2 ± √3", "x = −2 ± √3", "x = −2 ± √5", "x = −4 ± √3"]'::jsonb,1,'x = (−4 ± √12)/2.','original'),
